function test_bug_CantDisableBlacklistedExtension() public {
    address EXTENSION_1 = TEST_ADDR_1;
    address EXTENSION_2 = TEST_ADDR_2;
    address bobSafe = address(bob.safe);

    // Extensions 1 and 2 are whitelisted
